// Node-RED Function Node
function decimalToValue(decimal) {
    switch (decimal) {
        case 31: return 1;
        case 47: return 10;
        case 63: return 25;
        case 79: return 50;
        case 95: return 100;
        default: return 0;
    }
}

// Get input value from msg.payload
let inputDecimal = msg.payload;

// Convert to number if received as string
if (typeof inputDecimal === 'string') {
    inputDecimal = parseInt(inputDecimal, 10);
}

// Convert decimal to value
msg.payload = decimalToValue(inputDecimal);

// Add original value for reference
msg.original = inputDecimal;

return msg;

