// msg.payload is the status byte (number 0-255)
let status = msg.payload;

msg.payload = {
    FUNK_ON: (status & 0x04) !== 0, // Bit 2
    ALARM_ACC: (status & 0x02) !== 0, // Bit 1
    ALARM_SW: (status & 0x01) !== 0, // Bit 0
    reserved: (status & 0xF8) >> 3   // Bits 3-7, for future use
};

return msg;

